css:
[data-theme="dashy-light"] .section.tinted .card{
  /* Sur fond clair, la teinte se melange au blanc plutot qu'au noir, sinon le
     texte deviendrait illisible sur les teintes sombres. */
  background:color-mix(in srgb, var(--tile-color) 16%, var(--surface));
  border-color:color-mix(in srgb, var(--tile-color) 42%, var(--border));
  box-shadow:0 2px 6px rgba(0,0,0,.12);
  transition:transform .12s ease,box-shadow .12s ease,background .12s ease;
}

[data-theme="dashy-light"] .section.tinted .card:hover{
  background:color-mix(in srgb, var(--tile-color) 24%, var(--surface));
  box-shadow:0 4px 12px rgba(0,0,0,.16);
}

[data-theme="dashy-light"] .section.tinted .card:active{
  transform:translateY(1px);
  box-shadow:0 1px 2px rgba(0,0,0,.14);
}

[data-theme="dashy-light"] .service-icon{
  filter:none !important;
  opacity:1;
}

[data-theme="dashy-light"] .card:hover,
[data-theme="dashy-light"] .top-menu-item:hover,
[data-theme="dashy-light"] .action-btn:hover{
  background:var(--surface-2);
}

[data-theme="dashy-light"] .service-fallback,
[data-theme="dashy-light"] .section-header > i,
[data-theme="dashy-light"] .top-menu i,
[data-theme="dashy-light"] .icon-btn i{
  color:#111;
}

[data-theme="dashy-light"] .category-icon{
  color:var(--tile-color, var(--accent));
}

[data-theme="dashy-light"] .small-icon-btn:not(.delete-btn){
  color:var(--text) !important;
}
[data-theme="dashy-light"] .small-icon-btn:not(.delete-btn) i{
  color:var(--text) !important;
}

[data-theme="dashy-light"] button.delete-btn i{
  color:#ff6b6b !important;
}
[data-theme="dashy-light"] button.delete-btn:hover i{
  color:#ff8a8a !important;
}
